  "codebook": {
    "definition": "Credit-claiming is defined as a senator acting to generate the belief among constituents, the state, or the nation that they are personally or collaboratively responsible for causing the government to deliver a specific, successful outcome or benefit (such as securing federal funding, grants, passing an amendment, enacting a bill, or obtaining positive executive actions).",
    "clarification": "To classify a press release as credit-claiming (1), it must report on a completed, positive government action or benefit (e.g., funding obtained, a project approved, an amendment adopted, a bill passed into law) and explicitly state or strongly imply that the senator(s) played a key role in achieving it. The classic form includes announcing federal grants or projects awarded to their home state, as well as highlighting specific legislative amendments they wrote or championed that were successfully adopted in a passed bill.",
    "positive_examples": [
      {
        "document_id": "1862",
        "explanation": "The senators announce $12.5 million for Butte military projects, explicitly claiming that they 'delivered on their promise' and 'went to bat' to secure the federal funding."
      },
      {
        "document_id": "2697",
        "explanation": "Senator Inouye announces funding to control coqui frogs, taking direct personal credit for 'going looking and finding another federal funding source' after the primary emergency funds were denied."
      },
      {
        "document_id": "873",
        "explanation": "Senator Landrieu claims credit for the Medicare Administrator waiving a late enrollment penalty, noting that the decision was a direct response to her urgent letters and advocacy."
      }
    ],
    "negative_clarification": "Do not classify a text as credit-claiming (0) if the senator is merely introducing or cosponsoring a new bill that has not yet passed, expressing an opinion or taking a stance on an issue (position-taking), explaining a vote, conducting oversight (criticizing the administration or agencies), or sending letters advocating for a future action where no outcome has been secured yet. Symbolic actions (condolences, memorials, or commemorative resolutions) do not count as credit-claiming.",
    "negative_examples": [
      {
        "document_id": "57",
        "explanation": "Senator Kennedy is introducing legislation to enhance stem cell research. Because the bill is only being introduced and has not passed, no benefit has been successfully delivered, making it position-taking/advertising."
      },
      {
        "document_id": "656",
        "explanation": "Senator Kerry is criticizing the Bush administration over a ports deal. Since this is an expression of criticism and policy stance without claiming credit for securing a concrete benefit, it is not credit-claiming."
      },
      {
        "document_id": "4122",
        "explanation": "The senators are announcing an upcoming oversight hearing and investigation into tax-delinquent Medicaid providers. This represents legislative oversight and investigation, rather than claiming credit for a completed material benefit or legislative success."
      }
    ]
  }
}
